db.users.insertOne({
  _id: "u_42",                       // custom string _id
  name: "Ada Lovelace",
  email: "ada@example.com",
  address: {                         // nested subdocument
    street: "221B Baker St",
    city: "London",
    geo: { type: "Point", coordinates: [-0.16, 51.52] }
  },
  tags: ["math", "computing"],       // array of scalars
  orders: [                          // array of subdocuments
    { id: "o1", total: NumberDecimal("99.50"), at: new Date() },
    { id: "o2", total: NumberDecimal("14.00"), at: new Date() }
  ],
  meta: { visits: NumberLong(0) }    // 64-bit int, not double
})

// ordered: true (default) stops at the first duplicate-key error
db.products.insertMany([
  { _id: "p1", name: "A" },
  { _id: "p1", name: "duplicate" },   // E11000 — stops here
  { _id: "p2", name: "B" }            // never attempted
], { ordered: true })

// ordered: false attempts all and reports errors at the end
db.products.insertMany([
  { _id: "p3", name: "C" },
  { _id: "p3", name: "dup" },         // fails but continues
  { _id: "p4", name: "D" }            // still attempted
], { ordered: false })

// Price between 10 and 100, AND inStock
db.products.find({
  price: { $gte: 10, $lt: 100 },
  inStock: true
})

// Category in any of these (uses index on category if present)
db.products.find({ category: { $in: ["books", "music", "games"] } })

// OR of two different field conditions
db.products.find({
  $or: [
    { "discount.pct": { $gte: 20 } },
    { clearance: true }
  ]
})

// Include only name and price; suppress _id
db.products.find(
  { inStock: true },
  { name: 1, price: 1, _id: 0 }
)

// Exclude a big field (e.g., a stored HTML blob)
db.posts.find({}, { body: 0 })

// Project nested array element by index (only first tag)
db.posts.find({}, { "tags.0": 1 })

// Project specific subdoc fields with dot notation
db.users.find({}, { "address.city": 1, "address.geo": 1 })

db.users.createIndex({ email: 1 }, { unique: true })
db.products.createIndex({ category: 1, price: -1 })   // compound
db.products.createIndex({ createdAt: -1 })

