db.events.createIndex({ status: 1, createdAt: -1 })

db.products.getIndexes()
db.products.dropIndex("category_1_price_-1")

db.orders.aggregate([
  { $match: { status: "shipped", createdAt: { $gte: ISODate("2024-01-01") } } },
  { $group: {
      _id: "$customerId",
      totalSpent: { $sum: "$total" },
      orderCount: { $sum: 1 },
      avgOrder: { $avg: "$total" }
  }},
  { $sort: { totalSpent: -1 } },
  { $limit: 10 }
])

db.orders.aggregate([
  { $match: { status: "shipped" } },
  { $lookup: {
      from: "customers",
      localField: "customerId",
      foreignField: "_id",
      as: "customer"
  }},
  { $unwind: "$customer" },          // flatten the 1-element array
  { $project: { orderId: "$_id", customerName: "$customer.name", total: 1 } }
])

db.users.insertOne({
  name: "Ada",
  addresses: [
    { label: "home", city: "London", zip: "NW1" },
