db.createCollection("users", {
  validator: { $jsonSchema: {
    bsonType: "object",
    required: [ "name", "email", "createdAt" ],
    properties: {
      name:      { bsonType: "string", maxLength: 100 },
      email:     { bsonType: "string", pattern: "^[^@]+@[^@]+\\.[^@]+$" },
      age:       { bsonType: "int", minimum: 0, maximum: 150 },
      role:      { enum: [ "admin", "user", "guest" ] },
      addresses: {
        bsonType: "array",
        items: {
          bsonType: "object",
          required: [ "city", "zip" ],
          properties: {
            city: { bsonType: "string" },
            zip:  { bsonType: "string", pattern: "^[0-9]{5}(-[0-9]{4})?$" }
          }
        }
      },
      createdAt: { bsonType: "date" }
    },
    additionalProperties: false
  }},
  validationLevel: "strict",
  validationAction: "error"
})

db.createCollection("temperatures", {
  timeseries: {
    timeField: "ts",
    metaField: "deviceId",
    granularity: "seconds"        // "seconds" | "minutes" | "hours"
  },
  expireAfterSeconds: 60 * 60 * 24 * 90    // 90-day TTL
})

db.temperatures.insertMany([
  { ts: new Date(), deviceId: "d1", temp: 22.5, humidity: 45 },
  { ts: new Date(), deviceId: "d2", temp: 18.0, humidity: 52 }
])

// Time-range + meta query is fast
db.temperatures.find({
  deviceId: "d1",
  ts: { $gte: ISODate("2024-01-01"), $lt: ISODate("2024-01-02") }
}).sort({ ts: 1 })

const { MongoClient } = require("mongodb")

const uri = process.env.MONGODB_URI
// e.g.: "mongodb+srv://user:pass@cluster0.x.mongodb.net/shop?retryWrites=true&w=majority&appName=orders-api"

let client
async function getDb() {
  if (!client) {
    client = new MongoClient(uri, {
      maxPoolSize: 50,           // tune per service
      minPoolSize: 5,
      serverSelectionTimeoutMS: 5000,
      connectTimeoutMS: 3000,
      socketTimeoutMS: 30000,
      readPreference: "primary",
      writeConcern: "majority",
      retryWrites: true,
      monitorCommands: true      // enables command monitoring events
    })
    client.on("commandSucceeded", e => logSlowIfSlow(e))
    await client.connect()
  }
  return client.db("shop")
}

async function shutdown() {
  if (client) await client.close()
}
